    "audit_result": {
      "property_id": "PROP-e5782b58-pre-006",
      "classification": "vulnerability",
      "code_path": "src/app/actions.ts::completeRegistration::L200-272",
      "proof_trace": "`completeRegistration` performs no Discord guild membership or generation role verification — it only validates that the authenticated user's `supabase_auth_user_id` exists in the pre-populated `member.members` table (L215-231). The only guild check (`is_in_server` via `fetchMemberStatus`) that existed was at the auth callback (auth/callback/route.ts:L105-119) and is entirely commented out, marked '一時的にコメントアウト'. The generation role check (`has_role(generation_role)`) is absent from every code path in the registration flow.",
      "attack_scenario": "A former club member (whose Discord UID and `supabase_auth_user_id` remain in `member.members` after leaving the server) authenticates via Discord OAuth — the commented-out guild check at the auth callback passes silently — then visits the kiosk to scan a new card, generating a `temp_registrations` token, and calls `completeRegistration` to complete card registration with no live Discord guild or role re-verification.",
      "checklist_id": "PROP-e5782b58-pre-006"
    },
    "text": "Registration must verify Discord guild membership and generation role before creating user.",
    "assertion": "forall completeRegistration(token, user): user.in_guild(target_guild) AND user.has_role(generation_role)",
    "covers": "SG-004",
    "severity": "HIGH",
    "type": "pre-condition"
  }
}

